const b=$json.body || $json;
const requestId=String(b.request_id || ('wf126-'+Date.now()));
const dealId=b.deal_id || null, leadId=b.lead_id || null, propertyId=b.property_id || null, readinessId=b.transaction_readiness_id || null;
const agreementType=String(b.agreement_type || '').toLowerCase();
const closingDate=b.closing_date || b.target_closing_date || null;
const statusInput=String(b.closing_status || b.status || '').toLowerCase();
const titleStatus=String(b.title_status || '').toLowerCase(), attorneyStatus=String(b.attorney_status || '').toLowerCase(), fundingStatus=String(b.funding_status || '').toLowerCase(), buyerStatus=String(b.buyer_status || b.assignee_status || '').toLowerCase();
const dnc=Boolean(b.dnc), missing=[];
if(!dealId) missing.push('deal_id'); if(!leadId) missing.push('lead_id'); if(!propertyId) missing.push('property_id'); if(!readinessId) missing.push('transaction_readiness_id'); if(!agreementType) missing.push('agreement_type');
const blockers=[],bad=['failed','issue','blocked','rejected'];
if(bad.includes(titleStatus)) blockers.push('title'); if(bad.includes(attorneyStatus)) blockers.push('closing_attorney'); if(bad.includes(fundingStatus)) blockers.push('funding'); if(bad.includes(buyerStatus)) blockers.push('buyer_or_assignee');
if(Array.isArray(b.closing_conditions)) for(const c of b.closing_conditions) if(c && String(c.status || '').toLowerCase() !== 'complete') blockers.push(String(c.name || 'closing_condition'));
let status='blocked',nextState='closing_review',route='human_review',reason='Closing coordination requires review';
if(dnc){status='suppressed';nextState='closing_coordination';route='none';reason='DNC suppresses communication only; closing state is retained';}
else if(missing.length){status='blocked';nextState='missing_closing_inputs';reason='Required closing coordination identity is missing';}
else if(blockers.length){status='blocked';nextState='closing_blocked';reason='One or more closing conditions are unresolved';}
else if(statusInput==='closed'||statusInput==='funded'||statusInput==='recorded'){status='closed';nextState='post_close';route='wf-043-post-close-assignment-completion';reason='Closing outcome indicates transaction is complete';}
else if(statusInput==='ready'||(titleStatus==='clear'&&attorneyStatus==='ready'&&fundingStatus==='ready'&&buyerStatus==='ready')){status='closing_ready';nextState='closing_scheduled';reason='Core closing readiness conditions are satisfied; confirm closing appointment and final documents';}
else{status='in_progress';nextState='closing_coordination';reason='Closing coordination remains in progress';}
const id='closing-coordination:'+dealId+':'+requestId+':v1',uniqueBlockers=[...new Set(blockers)];
return [{json:{workflow:'WF-126',workflow_version:'1.0',request_id:requestId,closing_coordination_id:id,transaction_readiness_id:readinessId,lead_id:leadId,property_id:propertyId,deal_id:dealId,agreement_type:agreementType,status,next_state:nextState,route,reason,closing_date:closingDate,title_status:titleStatus,attorney_status:attorneyStatus,funding_status:fundingStatus,buyer_status:buyerStatus,blockers:uniqueBlockers,critical_dates:{closing_date:closingDate,days_until_closing:closingDate?Math.ceil((new Date(closingDate).getTime()-Date.now())/86400000):null},requirements:['title/ownership verification','closing attorney or title company confirmation','executed agreement copy'],guardrails:{executed_agreement_required:true,no_invented_title_or_legal_facts:true,unresolved_blockers_prevent_closing_ready:true,human_closing_confirmation_required:true,dnc_suppresses_communication_not_transaction_state:true},crm_activity:{activity_type:'closing_coordination',subject:'WF-126 closing coordination - '+status,lead_id:leadId,property_id:propertyId,deal_id:dealId,external_id:id,external_source:'wholesaling-os-closing',metadata:{status,next_state:nextState,route,reason,closing_date:closingDate,blockers:uniqueBlockers}}}}];
